import{_ as i,o as e,c as r,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Contenido Programático: Algorítmica y Programación (APT1312)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Algoritmica_y_Programacion/Contenido_Programatico.md","filePath":"materias/Algoritmica_y_Programacion/Contenido_Programatico.md"}'),s={name:"materias/Algoritmica_y_Programacion/Contenido_Programatico.md"};function d(n,a,l,t,c,u){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="contenido-programatico-algoritmica-y-programacion-apt1312" tabindex="-1">Contenido Programático: Algorítmica y Programación (APT1312) <a class="header-anchor" href="#contenido-programatico-algoritmica-y-programacion-apt1312" aria-label="Permalink to &quot;Contenido Programático: Algorítmica y Programación (APT1312)&quot;">​</a></h1><p>Este documento contiene el desglose de las unidades curriculares para la materia de Algorítmica y Programación, según el Documento Rector del PNFI.</p><h2 id="trayecto-i-duracion-3-trimestres" tabindex="-1">Trayecto I (Duración: 3 Trimestres) <a class="header-anchor" href="#trayecto-i-duracion-3-trimestres" aria-label="Permalink to &quot;Trayecto I (Duración: 3 Trimestres)&quot;">​</a></h2><hr><h3 id="unidad-1-algoritmo-y-programas" tabindex="-1">Unidad 1: Algoritmo y Programas <a class="header-anchor" href="#unidad-1-algoritmo-y-programas" aria-label="Permalink to &quot;Unidad 1: Algoritmo y Programas&quot;">​</a></h3><ul><li>Concepto de Algoritmos y Programas.</li><li>Lenguaje algorítmico y de programación.</li><li>Partes de un algoritmo.</li><li>Características y elementos para construir un algoritmo.</li><li>Formas de representar un algoritmo: Lenguaje Natural, pseudocódigo y diagrama de flujo.</li><li>Traza de un algoritmo (corrida en frío).</li></ul><h3 id="unidad-2-estandares-de-calidad-en-el-diseno-de-algoritmos-y-construccion-de-programas" tabindex="-1">Unidad 2: Estándares de Calidad en el Diseño de Algoritmos y Construcción de Programas <a class="header-anchor" href="#unidad-2-estandares-de-calidad-en-el-diseno-de-algoritmos-y-construccion-de-programas" aria-label="Permalink to &quot;Unidad 2: Estándares de Calidad en el Diseño de Algoritmos y Construcción de Programas&quot;">​</a></h3><ul><li>Introducción a los estándares de calidad.</li><li>Formas y técnicas de documentar algoritmos y programas.</li></ul><h3 id="unidad-3-datos-y-entidades-primitivas" tabindex="-1">Unidad 3: Datos y Entidades Primitivas <a class="header-anchor" href="#unidad-3-datos-y-entidades-primitivas" aria-label="Permalink to &quot;Unidad 3: Datos y Entidades Primitivas&quot;">​</a></h3><ul><li>Concepto y diferencia entre dato e información, tipos de datos.</li><li>Los Operadores: Concepto y tipos de operadores.</li><li>Las Expresiones: concepto, tipos y evaluación de expresiones.</li><li>Los Identificadores: Concepto, reglas de escritura.</li><li>Las Variables: clasificación según su contenido (numéricas, lógicas y alfanuméricas) y su uso (de trabajo, contador y acumulador).</li><li>Constantes.</li></ul><h3 id="unidad-4-metodologia-para-el-analisis-y-planteamiento-de-problemas" tabindex="-1">Unidad 4: Metodología para el Análisis y Planteamiento de Problemas <a class="header-anchor" href="#unidad-4-metodologia-para-el-analisis-y-planteamiento-de-problemas" aria-label="Permalink to &quot;Unidad 4: Metodología para el Análisis y Planteamiento de Problemas&quot;">​</a></h3><ul><li>Identificación del Problema.</li><li>Identificación de los datos necesarios (entradas).</li><li>Identificación de los datos a obtener (salidas).</li><li>Descripción de las operaciones a utilizar (cálculos).</li><li>Descripción de los pasos para llegar a la solución (procesos).</li></ul><h3 id="unidad-5-programacion-estructurada" tabindex="-1">Unidad 5: Programación Estructurada <a class="header-anchor" href="#unidad-5-programacion-estructurada" aria-label="Permalink to &quot;Unidad 5: Programación Estructurada&quot;">​</a></h3><ul><li>Teoremas de la programación estructurada.</li><li>Estructuras de control: <ul><li><strong>Estructuras de decisión:</strong> concepto, tipos y sintaxis: Condicional, simples, dobles, múltiples, anidadas y selectiva.</li><li><strong>Estructuras de control iterativas:</strong> Concepto y tipos, Ciclo Mientras y Repetir: sintaxis y métodos para salir del ciclo. Ciclo Para: Sintaxis. Ciclos anidados.</li></ul></li></ul><h3 id="unidad-6-programacion-modular" tabindex="-1">Unidad 6: Programación Modular <a class="header-anchor" href="#unidad-6-programacion-modular" aria-label="Permalink to &quot;Unidad 6: Programación Modular&quot;">​</a></h3><ul><li>Funciones y procedimientos: Definición y Declaración.</li><li>Ámbito de variables: Datos locales y globales.</li><li>Llamada de una función y pase de parámetros.</li></ul><h3 id="unidad-7-arreglos" tabindex="-1">Unidad 7: Arreglos <a class="header-anchor" href="#unidad-7-arreglos" aria-label="Permalink to &quot;Unidad 7: Arreglos&quot;">​</a></h3><ul><li>Los arreglos: Definición, clasificación y operaciones básicas.</li><li>Métodos de Ordenamiento.</li><li>Métodos de búsqueda.</li></ul><h3 id="unidad-8-tratamiento-de-cadenas-de-caracteres" tabindex="-1">Unidad 8: Tratamiento de Cadenas de Caracteres <a class="header-anchor" href="#unidad-8-tratamiento-de-cadenas-de-caracteres" aria-label="Permalink to &quot;Unidad 8: Tratamiento de Cadenas de Caracteres&quot;">​</a></h3><ul><li>Definición, funciones asociadas y operaciones con cadenas.</li></ul><h3 id="unidad-9-estructuras-de-registros" tabindex="-1">Unidad 9: Estructuras de Registros <a class="header-anchor" href="#unidad-9-estructuras-de-registros" aria-label="Permalink to &quot;Unidad 9: Estructuras de Registros&quot;">​</a></h3><ul><li>Definición, declaración y acceso.</li><li>Estructura y arreglo.</li></ul><h3 id="unidad-10-archivos" tabindex="-1">Unidad 10: Archivos <a class="header-anchor" href="#unidad-10-archivos" aria-label="Permalink to &quot;Unidad 10: Archivos&quot;">​</a></h3><ul><li>Concepto, estructura y acceso.</li><li>Tipos de archivo: datos y de textos.</li><li>Métodos para realizar la gestión de archivos.</li></ul><h3 id="unidad-11-punteros" tabindex="-1">Unidad 11: Punteros <a class="header-anchor" href="#unidad-11-punteros" aria-label="Permalink to &quot;Unidad 11: Punteros&quot;">​</a></h3><ul><li>Definición, declaración, operadores y operaciones.</li><li>Punteros y funciones.</li><li>Punteros y estructuras.</li></ul><h3 id="unidad-12-listas-enlazadas" tabindex="-1">Unidad 12: Listas Enlazadas <a class="header-anchor" href="#unidad-12-listas-enlazadas" aria-label="Permalink to &quot;Unidad 12: Listas Enlazadas&quot;">​</a></h3><ul><li>Concepto y clasificación.</li><li><strong>Listas simplemente enlazadas:</strong> fundamentos teóricos, clasificación, operaciones básicas: <ul><li>Declaración, punteros de cabecera y cola, operador de selección, inserción, búsqueda y eliminación de elementos.</li></ul></li><li><strong>Listas doblemente enlazadas y Circulares:</strong> Declaración, recorrido, inserción y eliminación de elementos.</li></ul><h3 id="unidad-13-recursividad" tabindex="-1">Unidad 13: Recursividad <a class="header-anchor" href="#unidad-13-recursividad" aria-label="Permalink to &quot;Unidad 13: Recursividad&quot;">​</a></h3><ul><li>Fundamentos teóricos: Definición, ámbito de aplicación, utilidad.</li><li>Ventajas y desventajas de la recursividad.</li><li>Diseño y Escritura de programas recursivos.</li></ul><h3 id="unidad-14-introduccion-a-las-estructuras-de-datos-dinamicas-avanzadas-pilas-colas-y-arboles" tabindex="-1">Unidad 14: Introducción a las Estructuras de Datos Dinámicas Avanzadas: Pilas, Colas y Árboles <a class="header-anchor" href="#unidad-14-introduccion-a-las-estructuras-de-datos-dinamicas-avanzadas-pilas-colas-y-arboles" aria-label="Permalink to &quot;Unidad 14: Introducción a las Estructuras de Datos Dinámicas Avanzadas: Pilas, Colas y Árboles&quot;">​</a></h3><ul><li>Definición, especificaciones y tipos.</li><li>Funcionalidades e implementación básica.</li></ul>',32)])])}const p=i(s,[["render",d]]);export{g as __pageData,p as default};
